window.RP_SESSION={"id":"S-28dec576b699","messages":[{"id":"RP-III-0085193","time":"2026-04-29T01:35:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085194","time":"2026-04-29T01:35:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085195","time":"2026-04-29T01:35:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085196","time":"2026-04-29T01:35:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"어린 시절부터 영웅을 꿈꿨다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085197","time":"2026-04-29T01:35:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"막연한 이야기였다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085198","time":"2026-04-29T01:36:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"검을 들고 사악한 적들을 무찌르고 동료들을 이끄는 그런 막연한 꿈 말이다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085199","time":"2026-04-29T01:38:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"그 즈음의 남자아이라면 으레 그렇지 않은가.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085200","time":"2026-04-29T01:38:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"기사가 된다면 그리 될 수 있을 줄 알았다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085201","time":"2026-04-29T01:39:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"멍청한 가문에서는 명예로운 기사 따윈 가당치도 않았고.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085202","time":"2026-04-29T01:39:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"그래서 집을 나왔다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085203","time":"2026-04-29T01:40:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"몇 년이나 방황했다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085204","time":"2026-04-29T01:41:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"그 모든 방황이 언젠가는 영웅이 된다면 검로가 될 줄 알았다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085205","time":"2026-04-29T01:41:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"드디어 길을 찾았을 때, 내가 해온 것들은 엉터리 휘적거림에 지나지 않았음을 깨달았다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085206","time":"2026-04-29T01:42:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"길이 보인다면 길을 좇으면 될 줄 알았다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085207","time":"2026-04-29T01:42:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"그제야 알았다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085208","time":"2026-04-29T01:42:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"빛을 좇아서는 내 그림자만 길어진다는 걸.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085209","time":"2026-04-29T01:43:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"누군가에게 돌아올 길이 되어주기를.\n\n의지가 되어주기를 소망했으나.\n\n내 부족함만이 선명해질 뿐이었다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085210","time":"2026-04-29T01:44:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"검이 많이 무뎌졌구나.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085211","time":"2026-04-29T01:46:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"비척비척.\n\n검 두 자루만을 들고서.\n\n길을 따라.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085212","time":"2026-04-29T01:48:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 헤헤이~ 총각! 이런 밤에 돌아다니면, 늑대가 물어간다? \"\n\n울타리 위에 앉아있던 머챈트가 톡-! 내려오며 말을 던졌습니다.\n\n\" 한 잔 할래? \"\n\n찰랑. 그녀의 손엔 오늘도 술병이 하나 들려 있습니다.","characters":["P-92738ae601c0"]},{"id":"RP-III-0085213","time":"2026-04-29T01:49:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...술인가?\"\n\n예상치도 못했던 타이밍에 만난 그녀.\n\n잠시 놀랐지만 마른 세수 한번에.\n\n\"마다 않지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085214","time":"2026-04-29T01:51:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 치, 폼 잡기는 ㅎ. 인상을 보니까 어디 된통 뒤집어 쓴 모양인데, 세금이라도 잔뜩 나왔나? 아님, 또 악몽? \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085215","time":"2026-04-29T01:53:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...큭큭...\"\n\n입꼬리만 슬며시 올라가서는.\n\n\"그냥. 내가 너무 오래 헤매었나 싶군.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085216","time":"2026-04-29T01:54:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 으엑- 뭐래에... 근데, 마땅히 마실덴 없고. 지금 시내로 나가는 것도 귀찮고. 그냥 좀 걸으면서 한 잔 하고 있었거던. 괜찮지? 술산책. \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085217","time":"2026-04-29T01:55:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그러다가 술취해서 나자빠져 자면 진짜로 늑대가 물어간다네.\"\n\n\"같이 마시다가 깨워줄 말동무가 필요하겠군.\"\n\n\"술 산책. 그래 좋지. 한잔 주게나.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085218","time":"2026-04-29T01:56:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 응응~ 말동무, 술동무. 이런 밤에 혼자 돌아다니는 것 보단 둘이 걷는게 낫지. 뭐가 튀어나올 지 모르니까. \"\n\n머챈트는 마시던 술병을 찰랑- 건넵니다.\n\n\" 아, 그럼 밤동무가 되나? \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085219","time":"2026-04-29T01:59:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"단어 선택 좀 보게.\"\n\n술잔을 낚아채듯 받고는 단숨에 절반을 벌컥벌컥.\n\n\"내가 지금 그리 인상을 쓰고 있던가? 취객 눈에도 보일만큼?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085220","time":"2026-04-29T02:00:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 너 말야. 가끔 네 얼굴을 잊어버리는거 아냐? \"\n\n그녀는 가까이 다가와 한 쪽 눈썹을 올린 채 당신을 올려다봤습니다.\n\n\" 넌 웃지 않으면 험악하게 생겼어. \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085221","time":"2026-04-29T02:01:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그리곤 그녀의 손가락으로 토르번의 흉터를 흉내내듯 그으며 얘기했죠.","characters":["P-92738ae601c0"]},{"id":"RP-III-0085222","time":"2026-04-29T02:03:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"....자. 여기있네.\"\n\n미간은 과장스레 확 찌푸리고 제 손가락으로 한쪽 입을 잡아당겨 억지 웃음으로 어금니까지 보이게 만들어 놓고는.\n\n\"이이 우스니 보기 조응가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085223","time":"2026-04-29T02:05:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 쯧! 이제야 좀 낫네. \"\n\n머챈트는 토르번의 가슴을 손등으로 툭! 치며 만족스런 웃음을 지었습니다.\n\n\" 그리고 말야, 너 요새 냄새난다더라. 좀 씻어. \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085224","time":"2026-04-29T02:07:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"뭐.\"\n\n이게 낫다고. 입에서 손가락이 툭 빠지고는. 희한하다는 듯 한쪽 눈썹을 올리며 고민해봅니다.\n\n\"잘 씻고 다니거든. 아마 의뢰 직후 마주쳤는가보지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085225","time":"2026-04-29T02:08:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" ㅋㅋㅋㅋㅋ \"\n\n머챈트가 웃습니다.\n\n\" 너흰 씻어도 냄새나. 목이랑 귀 뒤도 박박 닦으란 말야. \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085226","time":"2026-04-29T02:09:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 발도 좀 말리고. 햇볕에. 그거 알지? 젖은 양말은 5분만 신고 다녀도 냄새가 아주 독하다구. \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085227","time":"2026-04-29T02:12:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"제 손등이나 옷깃을 잡고 냄새를 맡아보다가.\n\n\"윽. 잔소리....\"\n\n눈을 가늘게 뜨며 옷깃을 놓고 한숨을 푹 내쉽니다.\n\n\"조금 취했으면 그만 둘 법도 한데. 쉬지를 않는군. 그래선 남자들은 다들 도망갈 거라네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085228","time":"2026-04-29T02:15:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 그럼 나야 땡큐지? 요즘 세상은 말야, 괜찮은 남자 하나 찾기도 어려운 시절이라구. 이런 잔소리에 떠나갈정도면 안봐도 척이지. ...헹! 요새 남자들은 사내같질 않아서 원. \"\n\n머챈트도 내심 그 말에 뜨끔했는지, 밤하늘에 주먹질을 팍! 하며 과민하게 대꾸했습니다.\n\n\" 그리고, 내가 어디가 어때서? 머리 좋지. 성격 좋지, 연식은 좀 있어도 이정도 외모면 어디 빠지는 덴 없지 않나? \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085229","time":"2026-04-29T02:19:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"어후. 그래. 머챈트 양 정말 훌륭한 여자지. 아무래도 확실히. 아무렴.\"\n\n갑작스런 주먹질에 흠칫거리고 놀랐다가. 말을 돌리듯 다시 잔을 들이킵니다.\n\n\"푸하.\"\n\n시원하다는 듯 감탄사를 내뱉고는 빈 잔 바닥을 봅니다.\n\n\"사내가 사내다워야지. 요즘 너무 무르게 지냈더니, 나도 참 여려졌나보군.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085230","time":"2026-04-29T02:21:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 얼씨구 \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085231","time":"2026-04-29T02:21:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 진짜 절씨구다 진짜 \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085232","time":"2026-04-29T02:23:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...으잇? 반응이 왜 그런데.\"\n\n\"분명 내가 요즘 애들 뒷바라지를 하느라 여려진 게 틀림 없다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085233","time":"2026-04-29T02:26:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 남 뒷바라지 하는데, 여려질건 또 뭐람? \"\n\n머챈트는 핀잔하듯 얘기하곤 조용히 걸었습니다.\n\n잠깐의 정적.\n\n귀뚜라미가 우는 소리와 그 둘이 걸으며 즈려밟는 흙소리가 들렸습니다.\n\n\" 그런건, 지쳤다고 하는거야. \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085234","time":"2026-04-29T02:29:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n그러다 놀란 듯 발걸음이 뚝. 사박거리던 발소리는 반으로 줄고, 나란히 걷던 보폭이 뒤로 밀렸습니다.\n\n멍하니 머챈트의 뒤통수를 바라보고 있는 그.\n\n\"...지친건가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085235","time":"2026-04-29T02:32:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 그래~ 지치니까 예민하고, 예민하니까 과민반응하게 되고, 그러다보면 누가 그러겠지. '너 요새 좀 바뀐 거 같아~' 하면서~ 그럼 또 거기에 홀~랑 귀가 팔랑거려가지고 '내가 요즘 좀 바뀌었나...? 난 대체 뭘까... 난...' 이러면서 갑자기 지하로 막 파고내려가고 말야. 어우~ 소름끼쳐 연극이야 모야 \"\n\n머챈트는 머리에 손을 인채 눈을 감고 떠들며 걸어갔습니다.\n\n그러다 문득 토르번의 인기척이 없자 옆을 돌아봤습니다.\n\n\" 뭐야 깜짝이야, 갑자기 없어지고 그래 짜증나게 --; \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085236","time":"2026-04-29T02:36:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그러게. 지쳤나보군. 몰랐어.\"\n\n그녀가 뒤를 돌아보며 자신을 찾자, 그제서야 천천히 걸음을 옮겨 나란히. 그 말을 곱씹듯 턱을 슬슬 메만집니다.\n\n\"나도 모르게 궁상 떨고 있었군...?\"\n\n이제 가려운 곳을 찾았으니, 긁어야겠습니다. 그녀의 얼굴을 빤히 바라보며.\n\n\"머챈트 양은, 그럴 때 뭘하는가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085237","time":"2026-04-29T02:37:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 늑대한테 물려간 줄 알았네. -.-;; 무튼~ 좋게 말하면 궁상떨지 말란 얘기야. \"\n\n머챈트는 무심하게 투욱 툭 말을 던졌습니다.\n\n듣는 사람 생각은 없는건지, 아님 원래 이렇게 말을 툭툭 던져대는 여자인건지요.\n\n\" ... 그리고 더 좋게 얘기하면, \"\n\n그러다가도 본인도 말이 심했나? 싶었는지, 잠시 호흡을 가다듬고 얘기했습니다.\n\n\" 기죽지 말라는 얘기야. \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085238","time":"2026-04-29T02:37:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 나야 ... 뭐 ... \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085239","time":"2026-04-29T02:37:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그러고보니 난 뭘 하더라?\n\n\" 음. \"\n\n머챈트는 짧게 생각합니다. 그리고 작게 소리를 내며 정리합니다.\n\n\" 울어. 난 ㅋ \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085240","time":"2026-04-29T02:38:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 술도 마시고. 짜증도 내고. 화도 내고. 울고. 그런거지 뭐~\n\n나쁘지 않다고 생각해~ 나한테 솔직한 거. \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085241","time":"2026-04-29T02:43:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"...음.\"\n\n울기는 싫은 걸. 끔뻑끔뻑. 눈을 멍청하게 두어번 감았다 뜨다가.\n\n\"나한테 솔직하라고..?\"\n\n내 마음은 뭘 원하는지라고 진지하게 생각해본 적이 없었다.\n\n별똥별이 떨어지는 순간에 내가 사랑하는 걸 세가지 읊어보라고 하면. 별이 바닥에 쳐박히기 직전까지도 신중히 고민하다가 속사포처럼 답 세 개를 내놓겠지만.\n\n거기에 '나'라는 답은 없었을 거다.\n\n\"나는....?\"\n\n다시 한번 험상궂게 미간을 찌푸립니다. 새로운 숙제가 생긴 기분.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085242","time":"2026-04-29T02:45:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 너 뭐 -.- \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085243","time":"2026-04-29T02:46:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"으음. 아무래도 모르겠습니다. 품에 들어온 선글라스를 매만지며.\n\n\"글쎄. 여행이나 다녀올까 싶군.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085244","time":"2026-04-29T02:49:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 어휴. \"\n\n머챈트는 눈머리를 꾹 눌러 눈꼽을 떼냅니다.\n\n\" 여행? 아니면 여정? \"\n\n그리곤 허리춤에 뭐가 묻었는지 툭툭 털며 무심하게 물었습니다.\n\n\" 모험? 아니면 산책? \"\n\n그리곤 콧등을 몇 번 긁은 뒤 크게 기지개를 켰습니다.\n\n\" 아님, 도피? \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085245","time":"2026-04-29T02:57:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"여태 나랑은 어울리지 않는 길을 뒤쫓고 있었을지도 모른다는 생각에, 잠시 책을 읽어보도록 하자고 생각했다.\n\n여태 따라오던 길을 잃어버릴지라도, 새로운 내 길을 찾기로 했다.\n\n책에는 답이 있다. 글자를 펴고 읽는 것만으로는 남의 답을 좇게 된다.\n\n걸어서, 봐서, 들어서, 내 문장과 세상을 맞부딪히고 나서야 책이란 건 나의 답을 내어준다.\n\n그래서 산 책인가보다.\n\n\"산책이군.\"\n\n\"산책치고는 제법 오래걸리겠지만.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085246","time":"2026-04-29T03:04:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"잠깐의 정적.\n\n아니 조금 더 긴 정적.\n미안. 아주 살짝 더 긴.\n\n말 없이 걸음을 옮길 때마다 손에 들린 술병이 찰랑거리는 소리를 냈습니다.\n\n자박 자박 흙 밟는 소리는 유독 밤에 더 크게 들리는 것 같습니다.\n\n머챈트는 무슨 말을 꺼낼까 입을 옴싹이며 두 어번 열었다가 닫기를 반복합니다.\n\n그리곤 잠시 입술을 오무리고 생각합니다.\n\n잘 다녀오라, 얘길 해야 할까요?\n아님, 그러지말고 좀 더 해봐. 부추겨야 할까요?\n그것도 아니면\n\n\" 그래 그럼. \"\n\n그것도 아니면...\n\n\" 그러던가. \"\n\n아직 내 생각이 끝나지 않았는데,\n입이 먼저 움직입니다.\n\n쉿. 쉬잇...\n\n\" 그럴거 같더라구~ \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0085247","time":"2026-04-29T03:17:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"얼마나 긴 정적이었는지. 슬슬 시내가 보여왔습니다. 빈 잔을 머챈트에게 떠맡기듯 건네고 입꼬리를 올려 웃었습니다.\n\n\"잘 마셨다네. 나중에는 내가 사지.\"\n\n그리고 앞으로 주욱 뻗은 길을 다시 바라보았습니다.\n\n\"고향에 갈걸세. 길드에 어딘지 아는 사람들이 있을테니, 누가 걱정한다면 그리 갔다고 전해주게.\"\n\n그럴 것 같았죠. 그래도 괜찮겠죠. 글쎄요. 그러고 싶었을 거 거든요.\n\n아마도.\n\n아무렴.\n\n아무래도.\n\n확실히.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085248","time":"2026-04-29T03:23:00+09:00","room":"RP III","name":"머챈트","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 술산책이라더니. \"\n\n머챈트는 빈 잔을 건네 받았습니다.\n\n\" 짠을 한 번 못했네. \"\n\n그리곤 조용히 걸었습니다.","characters":["P-92738ae601c0"]},{"id":"RP-III-0085249","time":"2026-04-29T03:25:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"아차차.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085250","time":"2026-04-29T03:25:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"https://youtu.be/e8ex_rffXvg?si=yoas6Y8OrIJfM4Nh","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085251","time":"2026-04-29T03:25:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-7ba611cf90be"]},{"id":"RP-III-0085252","time":"2026-04-29T03:25:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
